-- M1 §5.11: identity_audit_log only grows. Generated by appendOnly() in
-- src/db/helpers/appendOnly.ts — UPDATE and DELETE raise KT001 for everyone including the owner,
-- and komtru_app holds INSERT and SELECT only. No hand-written grants: grantRuntimeAccess() finds
-- the trigger on every later migrate run and keeps the privileges narrow.
CREATE TRIGGER komtru_append_only BEFORE UPDATE OR DELETE ON "identity"."identity_audit_log" FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
--> statement-breakpoint
REVOKE ALL ON "identity"."identity_audit_log" FROM komtru_app;
--> statement-breakpoint
GRANT INSERT, SELECT ON "identity"."identity_audit_log" TO komtru_app;
